// The text of the four libraries built into the language (the Math functions, the CPU side of the GPU functions, the Text
// functions and the Lists functions): core/stdlib/Math.poly, Gpu.poly, Text.poly and Lists.poly. GENERATED by core/stdlib/sync-prelude.py: edit the .poly file, then run it.
// Prelude.cpp parses each once per process.
#include "front/PreludeText.hpp"

namespace polyir::front {

  StringView MathPreludeText() {
    return R"prelude(// MATH: small, general-purpose functions on floats, as part of polyir: the sign of a number, the part after its
// decimal point, a number held between two limits, and a slide from one value to another.
//
//   import "../../core/stdlib/Math.poly"       (from ideas/audio/Wave.poly: the path is relative to the importing file)
//
// The import is optional: these functions are BUILT INTO the language. A program that calls `sign`, `fract`,
// `clamp` or `mix` without defining or importing them gets this library added by the compiler (core/src/front/Prelude.cpp,
// which embeds the text of this file; after editing it run `python3 core/stdlib/sync-prelude.py`). Only the functions a program uses, and what they call, are added.
//
// Every function here is a `kernel func` on `float`s, so each one
//   * runs on the CPU like any function (and can be tested there),
//   * runs on a GPU inside other kernels (`--emit-msl`, `--emit-glsl`), and
//   * is checked by the kernel rules, so it can never use anything a GPU cannot do.
//
//   sign       -1, 0 or +1
//   fract      the part after the decimal point, 0 up to 1
//   clamp      a number held between a low and a high limit
//   mix        a slide from a to b (also called lerp)
extern func floorf(x: float) -> float

// -1 for a negative number, 0 for zero, +1 for a positive number. (Not the sine function.)
kernel func sign(x: float) -> float {
    if (x > 0.0) { return 1.0 }
    if (x < 0.0) { return 0.0 - 1.0 }
    return 0.0
}

// The part after the decimal point, always 0 up to (but not including) 1: fract(2.75) is 0.75
// and fract(-0.25) is 0.75 as well, so repeating patterns continue smoothly through zero.
kernel func fract(x: float) -> float {
    return x - floorf(x)
}

// x held between low and high: below low gives low, above high gives high.
kernel func clamp(x: float, low: float, high: float) -> float {
    if (x < low) { return low }
    if (x > high) { return high }
    return x
}

// Slide from a to b: t = 0 gives a, t = 1 gives b, t = 0.5 the middle (also called lerp).
kernel func mix(a: float, b: float, t: float) -> float {
    return a + (b - a) * t
}
)prelude";
  }

  StringView GpuPreludeText() {
    return R"prelude(// GPU: the CPU side of the functions a kernel uses to cooperate with its neighbours.
//
// A `kernel func` is written for ONE element and runs on thousands of GPU threads at once. Threads
// that touch the same memory need help: an ATOMIC update that cannot lose another thread's write,
// scratch memory shared by one WORKGROUP, and a BARRIER where the whole group waits for the slowest
// thread. The GPU back ends (`--emit-msl`, `--emit-glsl`) turn calls to the functions below into the
// real thing. On the CPU a kernel is just a function called once per element, one after another, so
// nothing can race and these are plain functions that do the same job sequentially:
//
//   atomicAdd(counts, slot, n)         counts[slot] += n          (whole numbers); returns the old value
//   atomicAddFloat(sums, slot, x)      sums[slot] += x            (floats); returns the old value
//   atomicMin(values, slot, n)         values[slot] = smaller of the two; returns the old value
//   atomicMax(values, slot, n)         values[slot] = larger of the two; returns the old value
//
//   groupSize()                        how many threads cooperate in one workgroup: 256 on the GPU, 1 here
//   localIndex(i)                      this thread's place within its group: i % 256 on the GPU, 0 here
//   groupIndex(i)                      the number of this thread's group: i / 256 on the GPU, i here
//   barrier()                          every thread of the group waits here until all have arrived
//
// A CPU "group" therefore has exactly one thread, so a kernel written correctly for ANY group size
// (as the examples are) gives the same answer here as on the GPU, which makes the CPU a reference.
//
// Like the Wave library these are BUILT IN: a program that calls them without defining or importing
// them gets this file added by the compiler (src/Prelude.nina; after editing it run
// `python3 stdlib/sync-prelude.py`). A program that defines one of the names itself keeps its own.

func atomicAdd(counts: ptr<i32>, slot: i32, amount: i32) -> i32 {
    let old: i32 = counts[slot]
    counts[slot] = old + amount
    return old
}

func atomicAddFloat(sums: ptr<float>, slot: i32, amount: float) -> float {
    let old: float = sums[slot]
    sums[slot] = old + amount
    return old
}

func atomicMin(values: ptr<i32>, slot: i32, candidate: i32) -> i32 {
    let old: i32 = values[slot]
    if (candidate < old) { values[slot] = candidate }
    return old
}

func atomicMax(values: ptr<i32>, slot: i32, candidate: i32) -> i32 {
    let old: i32 = values[slot]
    if (candidate > old) { values[slot] = candidate }
    return old
}

func groupSize() -> i32 {
    return 1
}

func localIndex(i: i32) -> i32 {
    return 0
}

func groupIndex(i: i32) -> i32 {
    return i
}

func barrier() -> i32 {
    return 0
}
)prelude";
  }

  StringView TextPreludeText() {
    return R"prelude(// TEXT: working with strings, as part of polyir. Built on the four string built-ins (`str(x)`, `s[i]`,
// `s.slice(from, to)`, `s.find(sub, from)`) and `len`, so it runs on every target.
//
//   import "../../stdlib/Text.poly"       (the path is relative to the importing file)
//
// The import is optional: these are BUILT INTO the language. A program that calls `split`, `trim` and the rest (or
// makes a `StringBuilder()`) without defining or importing them gets them added by the compiler (src/Prelude.nina,
// which embeds this file; after editing it run `python3 stdlib/sync-prelude.py`). Only what a program uses is added.
//
// Every function reads as a method too: `s.split(",")` is `split(s, ",")`. Positions count bytes, which are the
// characters of ASCII text.
//
//   contains startsWith endsWith      questions about a string
//   split lines join                  between one string and a list of them
//   trim replace repeat indent        new strings
//   indentRest                        what a multi-line `${…}` in a text block uses
//   fill                              `${name}` in a template read at run time, from a map of values
//   StringBuilder                     text built piece by piece

// Whether `part` occurs in `s`.
func contains(s: string, part: string) -> bool {
  return s.find(part) >= 0
}

func startsWith(s: string, prefix: string) -> bool {
  if (len(prefix) > len(s)) {
    return false
  }
  return s.slice(0, len(prefix)) == prefix
}

func endsWith(s: string, suffix: string) -> bool {
  if (len(suffix) > len(s)) {
    return false
  }
  return s.slice(len(s) - len(suffix), len(s)) == suffix
}

// The pieces of `s` between each `sep`: "a,b,,c" by "," is "a", "b", "", "c". An empty `sep` gives `s` alone.
func split(s: string, sep: string) -> mutarray<string> {
  let parts: mutarray<string>
  if (len(sep) == 0) {
    parts.push(s)
    return parts
  }
  var from: i64 = 0
  for (at = s.find(sep, 0); at >= 0; at = s.find(sep, from)) {
    parts.push(s.slice(from, at))
    from = at + len(sep)
  }
  parts.push(s.slice(from, len(s)))
  return parts
}

// The lines of `s` (split at each newline).
func lines(s: string) -> mutarray<string> {
  return split(s, "\n")
}

// The strings one after another, with `sep` between each two.
func join(parts: mutarray<string>, sep: string) -> string {
  var out: string = ""
  for (i = 0; i < len(parts); i = i + 1) {
    if (i > 0) {
      out = out + sep
    }
    out = out + parts[i]
  }
  return out
}

func isSpaceChar(c: char) -> bool {
  return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

// `s` without the spaces, tabs and newlines at its start and end.
func trim(s: string) -> string {
  var from: i64 = 0
  for (; from < len(s) && isSpaceChar(s[from]); ) {
    from = from + 1
  }
  var to: i64 = len(s)
  for (; to > from && isSpaceChar(s[to - 1]); ) {
    to = to - 1
  }
  return s.slice(from, to)
}

// `s` with every `old` written as `by`.
func replace(s: string, old: string, by: string) -> string {
  return join(split(s, old), by)
}

// `s` written `n` times.
func repeat(s: string, n: i64) -> string {
  var out: string = ""
  for (i = 0; i < n; i = i + 1) {
    out = out + s
  }
  return out
}

// Each line of `s` that is not empty, `n` spaces further in.
func indent(s: string, n: i64) -> string {
  let all: mutarray<string> = lines(s)
  let pad: string = repeat(" ", n)
  for (i = 0; i < len(all); i = i + 1) {
    if (len(all[i]) > 0) {
      all[i] = pad + all[i]
    }
  }
  return join(all, "\n")
}

// `s` with every line but the first `n` spaces further in: a multi-line value placed after `n` spaces stays lined up.
func indentRest(s: string, n: i64) -> string {
  let first: i64 = s.find("\n")
  if (first < 0) {
    return s
  }
  return s.slice(0, first + 1) + indent(s.slice(first + 1, len(s)), n)
}

// A template read at run time with each `${name}` written as `values[name]`; a name with no value is left as it is.
func fill(template: string, values: mutmap<string, string>) -> string {
  var out: string = ""
  var from: i64 = 0
  for (at = template.find("\${", 0); at >= 0; at = template.find("\${", from)) {
    let close: i64 = template.find("}", at)
    if (close < 0) {
      return out + template.slice(from, len(template))
    }
    out = out + template.slice(from, at) + filledName(template.slice(at, close + 1), values)
    from = close + 1
  }
  return out + template.slice(from, len(template))
}

// `${name}` as its value, or as it is when the map has none.
func filledName(placeholder: string, values: mutmap<string, string>) -> string {
  let name: string = trim(placeholder.slice(2, len(placeholder) - 1))
  if (values.has(name)) {
    return values[name]
  }
  return placeholder
}

// Text built piece by piece: `let out = StringBuilder()`, then `out.line("...")`, `out.add(...)`, and `out.text()`
// at the end. It is shared, not copied, so a helper can write into the caller's builder. `indent(n)` moves the lines
// added after it `n` spaces in, until `dedent()`.
struct StringBuilder(pieces: mutarray<string>, indents: mutarray<i64>) {
  // Text added as it is.
  func add(s: string) -> StringBuilder {
    this.pieces.push(s)
    return this
  }

  // A line: the current indent, the text, a newline.
  func line(s: string) -> StringBuilder {
    if (len(s) > 0) {
      this.pieces.push(repeat(" ", this.indentNow()))
    }
    this.pieces.push(s)
    this.pieces.push("\n")
    return this
  }

  // An empty line.
  func blank() -> StringBuilder {
    this.pieces.push("\n")
    return this
  }

  // Each of `all` as a line.
  func lines(all: mutarray<string>) -> StringBuilder {
    for (i = 0; i < len(all); i = i + 1) {
      this.line(all[i])
    }
    return this
  }

  func indent(n: i64) -> StringBuilder {
    this.indents.push(this.indentNow() + n)
    return this
  }

  func dedent() -> StringBuilder {
    if (len(this.indents) > 0) {
      this.indents.truncate(len(this.indents) - 1)
    }
    return this
  }

  func indentNow() -> i64 {
    if (len(this.indents) == 0) {
      return 0
    }
    return this.indents[len(this.indents) - 1]
  }

  func length() -> i64 {
    return len(this.text())
  }

  func isEmpty() -> bool {
    return this.length() == 0
  }

  // Everything added so far, as one string.
  func text() -> string {
    return join(this.pieces, "")
  }
}
)prelude";
  }

  StringView ListsPreludeText() {
    return R"prelude(// LISTS: working with arrays and mutarrays, as part of polyir. Built on `len`, `xs[i]` and `push`, so it runs on every target.
//
//   import "../../stdlib/Lists.poly"       (the path is relative to the importing file)
//
// The import is optional: these are BUILT INTO the language. A program that calls them without defining or importing them
// gets them added by the compiler (src/front/Prelude.cpp, which embeds this file; after editing it run
// `python3 core/stdlib/sync-prelude.py`). Only what a program uses is added. A `match` list pattern with a rest
// (`[first, ...rest]`) uses `drop`.
//
// Every function is generic and reads as a method too: `xs.drop(1)` is `drop(xs, 1)`, for an `array<T>` or a `mutarray<T>`.
//
//   first last      an end of a non-empty list
//   drop            a new list without the first n elements

// The first element (the list must have one).
func first<T>(xs: array<T>) -> T {
  return xs[0]
}

// The last element (the list must have one).
func last<T>(xs: array<T>) -> T {
  return xs[len(xs) - 1]
}

// A new list of the elements after the first `n`: [1, 2, 3] dropping 1 is [2, 3]. Dropping more than there are gives none.
func drop<T>(xs: array<T>, n: i64) -> mutarray<T> {
  let out: mutarray<T>
  for (i = n; i < len(xs); i = i + 1) {
    out.push(xs[i])
  }
  return out
}
)prelude";
  }

}  // namespace polyir::front
